groups.template:
@if(ecomStore.userInfo().roles.indexOf("OneCPQ Admin") != -1){
    @if(bundleGroup(); as bg){
                @if(toggleable()){    
                <div class="pt-2">
                    <p-panel class="pt-2" [collapsed]="collapsed()" [toggleable]="toggleable()" collapseIcon="pi pi-angle-left"
                        expandIcon="pi pi-angle-down">
                        <ng-template #header>
                            <div class="flex align-items-center gap-2">
                                <span class="font-bold">
                                    {{bg.label}}
                                </span>
                            </div>
                        </ng-template>
                        @if(toggleable()){
                        <ng-template #icons>
                            <button
                                class="p-0 p-ripple p-button p-component p-button-icon-only p-button-secondary p-button-rounded p-button-text p-panel-header-icon p-panel-toggler p-link"
                                (click)="setExpanded()">
                                <span [class]="'pi pi-angle-double-'+(collapsed() ? 'left':'down')"></span>
                            </button>
                        </ng-template>
                        }
                        <ng-container *ngTemplateOutlet="table"></ng-container>
                    </p-panel>
                </div>
            }
            @else {
                <ng-container *ngTemplateOutlet="table"></ng-container>
            }
            <ng-template #table>
    @if(bundleGroup(); as bg){
    @if(cartItemFeatureModels(); as cifs){
    <p-table size="small" styleClass="text-base " paginatorDropdownAppendTo="body"
        [paginator]="cifs.length >5?true:false" [rows]="10" [rowsPerPageOptions]="[5,10,20,50,75,100]" #dt
        responsiveLayout="stack" [value]="cifs">

        <ng-template #header>
            <tr>
                @for(property of bg.properties; track property){
                @let md = _.get(AppConst.bundleGroupColumns,property);
                <th
                    [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''">
                    {{_.get(AppConst.bundleGroupColumns,property)?.label}}</th>
                }
            </tr>
        </ng-template>
        <ng-template #body let-item let-rowIndex="rowIndex">
            <tr class="bundleGroupTable" (click)="navigate(item)">
                @for(property of bg.properties; track property){

                @let md = _.get(AppConst.bundleGroupColumns,property);
                @if(md?.editable && editable()) {
                <td [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''"
                    [pEditableColumn]="property" [pEditableColumnField]="property">
                    <span class="p-column-title">{{md.label}}</span>
                    @if(property === 'unitPrice'){

                    @let ftip = this.bundleGroupInterface()?.getPriceListDetail(item.featureTypeItem.id,'One Time');


                    @if(ftip?.isMatrix){
                    <span>

                        <p-button (click)="handleToggleMatrix(item.featureTypeItem,$event)" title="Matrix Detail"
                            styleClass="btb-rotate-45" icon="pi pi-thumbtack" [rounded]="true" [text]="true" />
                        <btb-shared-matrix-price-detail [cartItemFeature]="item"
                            [headerTitle]="(ftip?.matrixType ?? '') +' pricing - '+item.featureTypeItem.value"
                            [items]="ftip?.entries" [displayModal]="toggleViewModel()[item.featureTypeItem.id]">
                        </btb-shared-matrix-price-detail>
                    </span>
                    }
                    }
                    <p-cellEditor class="align-content-end">
                        <ng-template pTemplate="input">
                            @if(md.type === 'currency' || md.type === 'number'|| md.type === 'percentage') {
                            <input pInputText type="number" [(ngModel)]="item[property]">
                            }
                        </ng-template>
                        <ng-template pTemplate="output">
                            <span class="ref-link cursor-pointer">
                                {{getValue(item, property)}}
                            </span>
                        </ng-template>
                    </p-cellEditor>
                </td>    

                }
                @else {
                <td
                    [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''">
                    <span class="p-column-title">{{md?.label}}</span>
                    {{getValue(item, property)}}
                </td>
                }
                }
            </tr>
        </ng-template>
        <ng-template #footer *ngIf="bg.showSummary">
            <tr>
                @for(property of bg.properties; track property){
                @let md = _.get(AppConst.bundleGroupColumns,property);
                <td
                    [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''">
                    @if (md?.showSummary) {
                    {{_.get(summary(),property)}}
                    }

                </td>
                }
            </tr>
        </ng-template>
    </p-table>
    }
    }
</ng-template>
        }
}

actions.expr:
CONCAT('Flange / Angle Size must be greater than or equal to ',IIF(CONTAINS(optionFlangeangle, '$[Flange]'),
NUMBER(flangeSize),NUMBER(angleSize)
))

EVALUATE(
'var inp = input.arg1;
if((inp*2)%2 ==1 && Math.floor(inp*2) == inp *2) return Math.floor(inp);
return Math.round(input.arg1);',
NUMBER(modulesWoRounding)
)

CFLOAT(EVALUATE('
var WI = input.arg1;
var MaxW = input.arg2;
var BaseModule = input.arg3;
if(MaxW >0) return Math.ceil(WI/(parseInt(MaxW/BaseModule)*BaseModule));
return 1;
',
NUMBER(widthWi),
NUMBER(maxSectionWidth),
NUMBER(baseModuleWidth)
)
)

IIF(
(NUMBER(maxSectionWidth)>0),
CFLOAT(EVALUATE('
return Math.ceil(input.arg1);
',
NUMBER(noOfModules)/
NUMBER(totalWidthSections)
)),
NUMBER(noOfModules)
)

EVALUATE('
var casingOptions = input.arg1;
if(casingOptions =="Assembly") return Math.max(input.arg2,input.arg3); 
return Math.max(input.arg4,input.arg5,input.arg6,input.arg7); 
',
SELECTEDVALUE(casingOptions),
NUMBER(widthWi),
NUMBER(heightHi),
NUMBER(widthw1),
NUMBER(heighth1),
NUMBER(widthw2),
NUMBER(heighth2)
)

CONCAT(
EVALUATE('
var inp = input.arg1;
if(inp==10000) return "R3";
if(inp == 1600 || inp == 2000) return "R2";
return "R1";',
IIF(CONTAINS(productCategory,'$[FR240]'),
LOOKABOVE(NUMBER(maxWH),0,800,1600,10000),
LOOKABOVE(NUMBER(maxWH),0,1000,2000,10000)
)
),
SELECTEDVALUE(materialType)
)

CONCAT(
EVALUATE('
var inp = input.arg1;
var prdCategory = input.arg2;
if(inp==400 || inp == 600) return "R1";
if(inp == 800 || inp == 1000) return "R2";
if(inp == 10000 && prdCategory == "Normal") return "R4";
return "R3";',
IIF(CONTAINS(productCategory,'$[FR240]'),
LOOKABOVE(NUMBER(maxWH),0,400,800,10000),
(IIF(CONTAINS(productCategory,'$[FR120]'),
LOOKABOVE(NUMBER(maxWH),0,600,1000,10000),
LOOKABOVE(NUMBER(maxWH),0,600,1000,2000,10000)
))
),
SELECTEDVALUE(productCategory)
),
SELECTEDVALUE(materialType)
)

IIF(CONTAINS(optionFlangeangle,'$[Angle]'),0,EVALUATE('
var flange = input.arg1;
if( flange == NaN) flange = 0;
return Math.max(flange,input.arg2);
',
CFLOAT(OBJECTATTRIBUTEF(flangeangleUnique,'flange_size')),
 IIF((COUNT(customFlangeAngleSize) > 0),CFLOAT(SELECTEDVALUE(customFlangeAngleSize)),0)
)
)

EVALUATE('
var BaffleWidth = input.arg1;
var NoFullMod = input.arg2;
var HBaffleWidth = input.arg3;
var output = NoFullMod*Math.floor(BaffleWidth/100);
if(HBaffleWidth == 150) output = output+1;
return output;',
NUMBER(baffleWidth),
NUMBER(noOfFullModules),
NUMBER(halfBaffleWidth)
)

EVALUATE(
    '
    var H1 = input.arg1;
    var L1 = input.arg2;
    var NoSect1 = input.arg3;
    var NoBaffle1 = Math.ceil(input.arg4);
    var H2 = input.arg5;
    var L2 = input.arg6;
    var NoSect2 = input.arg7;
    var NoBaffle2 = Math.ceil(input.arg8);
    var FixedBaffleCost = input.arg9;
    var VarBaffleMin = input.arg10;
    var HourlyRate = input.arg11;
    return (((H1*L1/1000000*NoSect1*NoBaffle1)+(H2*L2/1000000*NoSect2*NoBaffle2))*VarBaffleMin*HourlyRate/60) + (((NoBaffle1*NoSect1)+(NoBaffle2*NoSect2))*FixedBaffleCost);

    ',
    NUMBER(heighth1),
    NUMBER(lengthl1),
    NUMBER(noOfSections1),
    NUMBER(noOfTotalBaffles1),
    NUMBER(heighth2),
    NUMBER(lengthl2),
    NUMBER(noOfSections2),
    NUMBER(noOfTotalBaffles2),
    CFLOAT(OBJECTATTRIBUTEV(countryWiseCost,'$[Fixed Baffle Cost]','cost')),
    CFLOAT(OBJECTATTRIBUTEV(countryWiseCost,'$[Time per Baffle SQM]','cost')),
    CFLOAT(OBJECTATTRIBUTEV(countryWiseCost,'$[Cost per Hour (SIL)]','cost'))
)

EVALUATE(
    '
    var H1 = input.arg1;
    var L1 = input.arg2;
    var NoSect1 = input.arg3;
    var NoBaffle1 = Math.ceil(input.arg4);
    var H2 = input.arg5;
    var L2 = input.arg6;
    var NoSect2 = input.arg7;
    var NoBaffle2 = Math.ceil(input.arg8);
    var FixedBaffleCost = input.arg9;
    var VarBaffleAssemblyMin = input.arg10;
    var HourlyRate = input.arg11;
    return (((L1/1000*NoSect1*NoBaffle1)+(L2/1000*NoSect2*NoBaffle2))*VarBaffleAssemblyMin*HourlyRate/60)
    +
    (((NoBaffle1*NoSect1)+(NoBaffle2*NoSect2))*FixedBaffleCost/2);

    ',
    NUMBER(heighth1),
    NUMBER(lengthl1),
    NUMBER(noOfSections1),
    NUMBER(noOfTotalBaffles1),
    NUMBER(heighth2),
    NUMBER(lengthl2),
    NUMBER(noOfSections2),
    NUMBER(noOfTotalBaffles2),
    CFLOAT(OBJECTATTRIBUTEV(countryWiseCost,'$[Fixed Baffle Cost]','cost')),
    CFLOAT(OBJECTATTRIBUTEV(countryWiseCost,'$[Baffle Installation Cost to Casing]','cost')),
    CFLOAT(OBJECTATTRIBUTEV(countryWiseCost,'$[Cost per Hour (SIL)]','cost'))
)
